('cmuo2jt7i001p2gzmfi2gc72n', 'marcha-leve-parada', 'Marcha leve parada', 'ENERGY', 'LOW_IMPACT_CARDIO', 'PHYSICAL', 1, 1, 'TIME_BASED', 'Ative circulacao com passos leves no lugar.', 'Elevar energia com movimento seguro e baixo impacto.', 120, NULL, NULL, NULL, 'LIGHT', 'Nenhum', 'marcha-leve-parada', 'marcha-leve-parada-guided-animation', '["Quando houver lentidao fisica sem exaustao intensa.","Antes de voltar para uma tarefa curta."]', '["Evite se houver dor, tontura ou falta de ar incomum."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Fique em pe com espaco ao redor.","Marche no lugar sem saltar.","Balance os bracos de forma leve.","Reduza o ritmo se a respiracao acelerar demais.","Finalize caminhando devagar por alguns segundos."]', '["Pise macio.","Mantenha joelhos soltos.","Olhe para frente."]', '["Respire em ritmo confortavel.","Fale uma frase curta para checar se o ritmo esta leve."]', '["Transformar em treino intenso.","Prender a respiracao.","Subir demais os joelhos."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.967Z', '2026-09-30T12:15:51.967Z'),
('cmuo2jt7k001q2gzmh9gib6c0', 'luz-e-janela', 'Luz e janela', 'ENERGY', 'RELAXATION', 'MENTAL', 1, 1, 'TIME_BASED', 'Use luz natural ou ambiente aberto para sinalizar reativacao suave.', 'Ajudar o corpo a sair do modo lento com um ajuste ambiental simples.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'luz-e-janela', 'luz-e-janela-guided-animation', '["Quando a energia cair em ambiente fechado.","Pela manha ou em pausas diurnas."]', '["Evite olhar diretamente para sol forte ou luz desconfortavel."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Aproxime-se de uma janela ou area iluminada.","Relaxe os olhos olhando para longe.","Respire sem pressa.","Observe tres detalhes do ambiente.","Volte com uma acao pequena."]', '["Mantenha o corpo apoiado.","Solte os ombros.","Piscar naturalmente ajuda os olhos."]', '["Respire pelo nariz se for confortavel.","Expire como se aliviasse peso dos ombros."]', '["Usar a pausa para abrir redes.","Forcar a vista.","Esperar energia imediata."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.968Z', '2026-09-30T12:15:51.968Z'),
('cmuo2jt7m001r2gzmdorsi4tm', 'luz-baixa-transicao', 'Luz baixa de transicao', 'SLEEP', 'RELAXATION', 'MENTAL', 1, 1, 'TIME_BASED', 'Prepare o ambiente com menos luz e menos estimulo visual.', 'Sinalizar ao corpo que o ritmo pode desacelerar.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'luz-baixa-transicao', 'luz-baixa-transicao-guided-animation', '["No inicio da noite.","Quando telas e luz forte estiverem mantendo voce alerta."]', '["Evite deixar o ambiente escuro se isso trouxer inseguranca."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Reduza uma luz forte.","Diminua brilho da tela se ainda precisar usa-la.","Afaste notificacoes.","Respire por alguns ciclos.","Escolha uma atividade calma para continuar."]', '["Mantenha uma postura confortavel.","Evite deitar se ainda precisa finalizar algo importante.","Solte a mandibula."]', '["Alongue a expiracao.","Nao force sonolencia."]', '["Apagar tudo de uma vez e voltar para o celular.","Transformar a rotina em obrigacao rigida.","Usar luz baixa enquanto consome conteudo acelerado."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.970Z', '2026-09-30T12:15:51.970Z'),
('cmuo2jt7n001s2gzm629h6y3o', 'celular-longe-da-cama', 'Celular longe da cama', 'SLEEP', 'WORK_BREAK', 'MENTAL', 1, 1, 'TIME_BASED', 'Crie uma pequena distancia fisica entre voce e a tela.', 'Reduzir o impulso de checar notificacoes antes de dormir.', 60, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'celular-longe-da-cama', 'celular-longe-da-cama-guided-animation', '["Quando o celular estiver puxando sua atencao na cama.","Antes do ritual de sono."]', '["Evite se voce precisa do aparelho por seguranca; nesse caso, deixe em modo silencioso e fora da mao."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Escolha um local fora do alcance da cama.","Ative modo silencioso ou foco, se possivel.","Coloque o carregador nesse local.","Volte para a cama sem abrir outro app.","Respire por tres ciclos."]', '["Movimente-se devagar.","Evite deitar segurando o celular.","Mantenha o quarto seguro e acessivel."]', '["Expire longo ao deixar o aparelho.","Respire naturalmente depois."]', '["Deixar o celular virado para cima.","Checar uma ultima coisa.","Usar outro dispositivo no lugar."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.972Z', '2026-09-30T12:15:51.972Z'),
('cmuo2jt7p001t2gzm0ske5ezi', 'pendencia-para-amanha', 'Pendencia para amanha', 'SLEEP', 'WRITING', 'MENTAL', 1, 1, 'WRITING', 'Tire uma pendencia da cabeca e coloque em um lugar confiavel.', 'Reduzir preocupacao noturna sem tentar resolver tudo.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Papel, bloco de notas ou campo de anotacao', 'pendencia-para-amanha', 'pendencia-para-amanha-guided-animation', '["Quando a mente listar tarefas na hora de dormir.","Depois de um dia com muitas pendencias."]', '["Evite abrir uma lista longa de planejamento completo."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Escreva uma pendencia que esta voltando na mente.","Defina apenas o primeiro passo de amanha.","Anote um horario aproximado para olhar isso.","Feche a nota.","Respire e diga: isso ficou registrado."]', '["Escreva em postura relaxada.","Evite usar luz forte.","Solte maos e ombros."]', '["Respire antes de escrever.","Expire ao finalizar a anotacao."]', '["Planejar a semana toda.","Abrir mensagens de trabalho.","Cobrar uma solucao imediata."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.973Z', '2026-09-30T12:15:51.973Z'),
('cmuo2jt7r001u2gzmuscew3i3', 'relaxamento-pes-cabeca', 'Relaxamento dos pes a cabeca', 'SLEEP', 'RELAXATION', 'MENTAL', 1, 1, 'RELAXATION', 'Percorra o corpo lentamente para soltar tensoes antes de dormir.', 'Ajudar o corpo a perceber seguranca e reduzir ativacao.', 300, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'relaxamento-pes-cabeca', 'relaxamento-pes-cabeca-guided-animation', '["Antes de dormir.","Quando o corpo estiver tenso no fim do dia."]', '["Evite se focar no corpo aumentar desconforto; volte para respiracao natural."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Deite ou sente-se com apoio.","Leve atencao aos pes.","Suba lentamente por pernas, quadril, tronco, ombros e rosto.","Em cada parte, solte o peso que for possivel.","Finalize respirando de forma natural."]', '["Use apoio para ficar confortavel.","Nao force alongamento.","Ajuste travesseiro ou cadeira se precisar."]', '["Expire ao soltar cada regiao.","Deixe a respiracao voltar ao natural."]', '["Tentar relaxar perfeitamente.","Prender o ar.","Ficar procurando sinais de problema."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.975Z', '2026-09-30T12:15:51.975Z')
INSERT INTO "public"."ExerciseInstruction" ("id", "slug", "title", "area", "category", "categoryGroup", "level", "unlockLevel", "instructionType", "shortDescription", "objective", "durationSeconds", "sets", "reps", "restSeconds", "intensity", "equipment", "imageKey", "animationPromptKey", "recommendedWhen", "avoidWhen", "contraindications", "howToSteps", "postureTips", "breathingTips", "commonMistakes", "safetyNotes", "createdAt", "updatedAt") VALUES
('cmuo2jt7t001v2gzmy5xngkkr', 'escaneamento-corporal', 'Escaneamento corporal', 'SLEEP', 'RELAXATION', 'MENTAL', 1, 1, 'RELAXATION', 'Observe o corpo sem tentar consertar tudo.', 'Criar uma transicao de presenca e descanso.', 600, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'escaneamento-corporal', 'escaneamento-corporal-guided-animation', '["Quando a mente estiver acelerada na cama.","Quando voce quiser uma pratica sem tela."]', '["Evite se a observacao corporal ficar angustiante; abra os olhos e procure apoio."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Feche ou suavize os olhos.","Observe contato do corpo com a superficie.","Passe atencao por partes do corpo.","Nomeie sensacoes de forma neutra.","Volte a respiracao natural quando a mente sair."]', '["Apoie a coluna.","Solte mandibula e testa.","Mantenha as maos confortaveis."]', '["Respire sem controlar demais.","Use a expiracao como sinal de descanso."]', '["Tentar dormir imediatamente.","Julgar distrações.","Fazer a pratica com tela ligada."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.977Z', '2026-09-30T12:15:51.977Z'),
('cmuo2jt7u001w2gzmkqj0cle9', 'nomear-humor-atual', 'Nomear o humor atual', 'MOOD', 'RELAXATION', 'MENTAL', 1, 1, 'TIME_BASED', 'Dê um nome simples ao que voce sente agora, sem se reduzir a isso.', 'Aumentar clareza emocional com gentileza.', 60, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'nomear-humor-atual', 'nomear-humor-atual-guided-animation', '["Quando o humor parecer confuso.","Antes de escolher uma acao de cuidado."]', '["Evite buscar uma palavra perfeita."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Pergunte: como esta meu humor agora?","Escolha uma palavra simples.","Perceba onde isso aparece no corpo.","Diga: isso e um estado, nao tudo que eu sou.","Escolha um cuidado pequeno."]', '["Sente-se com apoio.","Relaxe ombros e rosto.","Mantenha o olhar suave."]', '["Respire naturalmente.","Expire antes de escolher a palavra."]', '["Julgar o que apareceu.","Forcar pensamento positivo.","Tentar resolver tudo imediatamente."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.979Z', '2026-09-30T12:15:51.979Z'),
('cmuo2jt7w001x2gzmhe14jn2e', 'uma-coisa-boa-agora', 'Uma coisa boa agora', 'MOOD', 'WRITING', 'MENTAL', 1, 1, 'WRITING', 'Reconheca um ponto pequeno ou neutro que ainda existe no dia.', 'Treinar atencao para sinais positivos possiveis sem negar dificuldades.', 120, NULL, NULL, NULL, 'VERY_LIGHT', 'Papel, bloco de notas ou campo de anotacao', 'uma-coisa-boa-agora', 'uma-coisa-boa-agora-guided-animation', '["Quando o humor estiver baixo, mas voce conseguir escrever uma frase.","No fim de uma pausa curta."]', '["Evite usar a pratica para invalidar tristeza ou cansaco."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Pense em algo pequeno que nao foi ruim.","Escreva uma frase concreta.","Nomeie por que isso importou um pouco.","Respire antes de seguir.","Guarde sem precisar transformar em gratidao grande."]', '["Escreva de forma relaxada.","Deixe a frase ser simples.","Evite editar demais."]', '["Respire naturalmente.","Solte o ar ao terminar a frase."]', '["Forcar alegria.","Comparar seu dia com outros.","Desqualificar coisas pequenas."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.980Z', '2026-09-30T12:15:51.980Z'),
('cmuo2jt7y001y2gzma9ikmq3q', 'musica-curta-positiva', 'Musica curta positiva', 'MOOD', 'RELAXATION', 'MENTAL', 1, 1, 'TIME_BASED', 'Use uma musica curta para mudar o ritmo interno com intencao.', 'Apoiar o humor por meio de um estimulo escolhido, sem excesso de tela.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'musica-curta-positiva', 'musica-curta-positiva-guided-animation', '["Quando uma musica leve ajudar a regular o momento.","Quando voce quiser uma pausa emocional breve."]', '["Evite se abrir apps de musica virar rolagem infinita ou gatilho de comparacao."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Escolha uma musica conhecida e segura para voce.","Deixe a tela de lado enquanto toca.","Observe uma parte do som com atencao.","Respire durante o refrao ou trecho preferido.","Ao terminar, escolha uma acao pequena."]', '["Fique em uma posicao confortavel.","Relaxe rosto e ombros.","Evite volume alto demais."]', '["Respire junto com o ritmo, sem forcar.","Use a expiracao para soltar tensao."]', '["Abrir redes junto.","Usar musica para fugir de tudo por muito tempo.","Aumentar volume para cobrir desconforto."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.982Z', '2026-09-30T12:15:51.982Z'),
('cmuo2jt80001z2gzm8l2c7g11', 'diario-3-linhas', 'Diario de 3 linhas', 'MOOD', 'WRITING', 'MENTAL', 1, 1, 'WRITING', 'Escreva tres linhas para organizar o humor com simplicidade.', 'Expressar o estado atual sem transformar a escrita em analise longa.', 300, NULL, NULL, NULL, 'VERY_LIGHT', 'Papel, bloco de notas ou campo de anotacao', 'diario-3-linhas', 'diario-3-linhas-guided-animation', '["Quando o humor estiver pesado ou confuso.","Quando voce quiser se escutar sem julgamento."]', '["Evite reler varias vezes se isso aumentar autocritica."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Linha 1: hoje eu estou sentindo...","Linha 2: isso pode estar ligado a...","Linha 3: agora eu posso fazer uma coisa pequena, que e...","Leia apenas uma vez.","Feche com uma respiracao tranquila."]', '["Sente-se com apoio.","Relaxe a mao.","Escreva sem buscar palavras bonitas."]', '["Respire antes de cada linha.","Solte o ar antes da linha final."]', '["Escrever um julgamento de si.","Tentar encontrar causa perfeita.","Transformar em lista de problemas."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.984Z', '2026-09-30T12:15:51.984Z'),
('cmuo2jt8100202gzmda8hn8zy', 'mensagem-gentil-para-alguem', 'Mensagem gentil para alguem', 'MOOD', 'WRITING', 'MENTAL', 1, 1, 'WRITING', 'Crie uma pequena acao de conexao social com baixo esforco.', 'Apoiar bem-estar por meio de contato simples e seguro.', 300, NULL, NULL, NULL, 'VERY_LIGHT', 'Celular ou papel', 'mensagem-gentil-para-alguem', 'mensagem-gentil-para-alguem-guided-animation', '["Quando voce sentir vontade de se conectar.","Quando o humor estiver baixo e uma mensagem leve parecer possivel."]', '["Evite se o contato gerar conflito, cobranca ou risco para voce."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Pense em uma pessoa segura.","Escreva uma mensagem curta e sem cobranca.","Use algo simples, como: lembrei de voce hoje.","Envie apenas se parecer confortavel.","Se nao enviar, reconheca que pensar na conexao ja conta."]', '["Evite ficar rolando conversas antigas.","Mantenha a mensagem curta.","Use uma postura confortavel."]', '["Respire antes de enviar.","Solte o ar se vier ansiedade de resposta."]', '["Esperar resposta imediata.","Mandar mensagem longa demais.","Escolher alguem que aumenta tensao."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.986Z', '2026-09-30T12:15:51.986Z'),
('cmuo2jt8300212gzmi1nltpnv', 'yoga-bolso-coluna-leve', 'Yoga de bolso: coluna leve', 'BODY_MOVEMENT', 'YOGA', 'PHYSICAL', 1, 1, 'MOBILITY', 'Uma pratica curta de yoga leve para soltar coluna, ombros e respiracao.', 'Trazer movimento suave ao corpo sem virar treino intenso.', 360, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'yoga-bolso-coluna-leve', 'yoga-bolso-coluna-leve-guided-animation', '["Quando o corpo estiver rigido.","Quando voce quiser movimento leve sem sair do conceito de pausa."]', '["Evite se houver dor na coluna, tontura ou desconforto incomum."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Sente-se ou fique em pe com apoio.","Cresca a coluna inspirando.","Incline o tronco suavemente para um lado e depois para o outro.","Gire ombros devagar.","Finalize com tres respiracoes longas."]', '["Nao force amplitude.","Mantenha o pescoco confortavel.","Use cadeira como apoio se precisar."]', '["Inspire ao alongar a coluna.","Expire ao inclinar ou soltar ombros.","Volte ao natural se ficar desconfortavel."]', '["Fazer rapido demais.","Forcar torcao.","Comparar sua mobilidade com imagens de yoga."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.987Z', '2026-09-30T12:15:51.987Z'),
('cmuo2jt8500222gzmcxblrdw1', 'yoga-bolso-pausa-no-chao', 'Yoga de bolso: pausa no chao', 'BODY_MOVEMENT', 'YOGA', 'PHYSICAL', 1, 1, 'STRETCHING', 'Uma sequencia muito leve no chao para desacelerar corpo e mente.', 'Criar um fechamento corporal calmo com posturas simples e seguras.', 420, NULL, NULL, NULL, 'VERY_LIGHT', 'Tapete, toalha ou superficie confortavel', 'yoga-bolso-pausa-no-chao', 'yoga-bolso-pausa-no-chao-guided-animation', '["No fim do dia.","Quando voce quiser desacelerar sem tela."]', '["Evite se levantar ou deitar no chao for desconfortavel ou inseguro."]', '["Evite em caso de dor, lesao recente, tontura ou orientacao profissional para evitar impacto."]', '["Sente-se em uma superficie confortavel.","Apoie as maos nas pernas e respire.","Leve o tronco levemente a frente sem forcar.","Volte devagar e abrace os joelhos se for confortavel.","Finalize sentado, percebendo o ritmo da respiracao."]', '["Use almofada se precisar.","Mantenha joelhos relaxados.","Nao force lombar ou quadril."]', '["Inspire ao crescer a coluna.","Expire ao aproximar o tronco.","Respire naturalmente no final."]', '["Forcar flexibilidade.","Prender o ar.","Ficar em posicao que causa dor."]', '["Faca em ritmo confortavel.","Pare se sentir dor, tontura, falta de ar intensa ou desconforto incomum.","Os exercicios sao sugestoes de bem-estar e nao substituem orientacao profissional."]', '2026-09-30T12:15:51.989Z', '2026-09-30T12:15:51.989Z'),
