('cmuo2jtes00502gzm7r8hmzrc', 'ref_006_mov_01', 'Toque nos calcanhares', 'BODY_MOVEMENT', 'HOME_FUNCTIONAL', 'PHYSICAL', 1, 1, 'REPS_BASED', 'Movimento de flexao lateral curta no chao, alternando o toque das maos nos calcanhares com o abdomen ativo.', 'Pode ajudar a ativar obliquos e musculatura abdominal lateral.', 240, 2, '45 repeticoes', 30, 'MODERATE', 'Colchonete', 'ref_006_mov_01', 'ref_006_mov_01-guided-animation', '["fortalecer abdomen","fortalecer core","treino em casa","sem equipamentos","estabilidade corporal","sedentarismo leve"]', '["dor cervical","dor lombar forte","pos-operatorio abdominal","tontura ao deitar","gravidez sem orientacao"]', '["dor lombar","dor cervical","hernia abdominal","diastase sem orientacao","dor abdominal forte"]', '["Deite com joelhos flexionados e pes apoiados no chao.","Mantenha bracos ao lado do corpo e queixo relaxado.","Eleve levemente ombros e costelas, sem puxar o pescoco.","Toque ou aproxime a mao direita do calcanhar direito.","Volte ao centro e repita para o lado esquerdo.","Alterne os lados mantendo respiracao continua."]', '["Reduza a amplitude, mantenha o olhar diagonal para cima e pense em aproximar costelas do quadril sem tensionar o pescoco.","nao puxe a cabeca com as maos","pare se sentir dor lombar ou cervical"]', '["Expire ao tocar o calcanhar e inspire ao voltar ao centro."]', '["Girar o tronco rapido, puxar a cabeca ou perder a lombar totalmente do controle."]', '["nao puxe a cabeca com as maos","pare se sentir dor lombar ou cervical","mantenha movimento curto e controlado","evite prender a respiracao"]', '2026-09-30T12:15:52.229Z', '2026-09-30T12:15:52.229Z'),
('cmuo2jteu00512gzm2a1sow6v', 'ref_006_mov_02', 'Abdominal bicicleta', 'BODY_MOVEMENT', 'HOME_FUNCTIONAL', 'PHYSICAL', 3, 3, 'REPS_BASED', 'Abdominal alternado no chao, aproximando cotovelo e joelho opostos sem puxar o pescoco.', 'Pode ajudar a fortalecer abdomen e obliquos com movimento alternado de pernas e tronco.', 240, 2, '45 repeticoes', 40, 'MODERATE', 'Colchonete', 'ref_006_mov_02', 'ref_006_mov_02-guided-animation', '["fortalecer abdomen","fortalecer core","melhorar condicionamento","perder gordura corporal","treino em casa"]', '["dor cervical","dor lombar","hernia abdominal","diastase sem orientacao","desconforto ao flexionar tronco"]', '["dor lombar","dor cervical","hernia abdominal","diastase sem orientacao","desconforto ao flexionar tronco"]', '["Deite com lombar confortavel e maos leves atras da cabeca.","Eleve pernas e mantenha joelhos flexionados.","Aproxime joelho direito e cotovelo esquerdo sem puxar o pescoco.","Volte pelo centro e alterne para o outro lado.","Mantenha ritmo moderado, com controle da lombar.","Descanse se a tecnica comecar a cair."]', '["Use as maos apenas como apoio, gire pelo tronco e reduza a extensao das pernas se a lombar perder estabilidade.","nao puxe o pescoco","mantenha lombar controlada"]', '["Expire ao cruzar cotovelo e joelho, inspire ao trocar."]', '["Pedalar rapido demais, puxar a cabeca ou deixar a lombar arquear."]', '["nao puxe o pescoco","mantenha lombar controlada","reduza velocidade antes de aumentar repeticoes","pare se houver dor aguda"]', '2026-09-30T12:15:52.231Z', '2026-09-30T12:15:52.231Z'),
('cmuo2jtew00522gzm6g9dwybb', 'ref_006_mov_03', 'Torcao russa', 'BODY_MOVEMENT', 'HOME_FUNCTIONAL', 'PHYSICAL', 2, 2, 'REPS_BASED', 'Exercicio sentado com tronco inclinado, girando as maos de um lado ao outro sem colapsar a coluna.', 'Pode ajudar a fortalecer obliquos e melhorar controle rotacional do tronco.', 240, 2, '60 repeticoes', 40, 'MODERATE', 'Colchonete', 'ref_006_mov_03', 'ref_006_mov_03-guided-animation', '["fortalecer core","estabilidade corporal","equilibrio","treino em casa","sedentarismo"]', '["dor lombar","dor no quadril","tontura","dor ao rotacionar tronco","hernia abdominal sem orientacao"]', '["dor lombar","dor no quadril","tontura","dor ao rotacionar tronco","hernia abdominal sem orientacao"]', '["Sente com joelhos flexionados e pes no chao.","Incline o tronco um pouco para tras sem arredondar a lombar.","Una as maos a frente do peito.","Gire o tronco para a direita com controle.","Volte ao centro e gire para a esquerda.","Mantenha o movimento pequeno se perder postura."]', '["Cresca a coluna, mantenha costelas organizadas e deixe o giro vir do tronco, nao dos ombros isolados.","mantenha pes apoiados se for iniciante","evite carga externa nesta versao"]', '["Expire durante o giro e inspire ao retornar ao centro."]', '["Mover apenas os bracos, arredondar a lombar ou usar impulso."]', '["mantenha pes apoiados se for iniciante","evite carga externa nesta versao","nao force amplitude","pare se a lombar incomodar"]', '2026-09-30T12:15:52.232Z', '2026-09-30T12:15:52.232Z'),
('cmuo2jtey00532gzm2vhzkrj0', 'ref_006_mov_04', 'Toque no ombro em prancha', 'BODY_MOVEMENT', 'HOME_FUNCTIONAL', 'PHYSICAL', 3, 3, 'REPS_BASED', 'Em prancha alta, alterna o toque das maos nos ombros mantendo quadris estaveis.', 'Pode ajudar a fortalecer core, ombros e estabilidade corporal em prancha.', 240, 2, '60 repeticoes', 45, 'MODERATE', 'Colchonete', 'ref_006_mov_04', 'ref_006_mov_04-guided-animation', '["fortalecer core","estabilidade corporal","equilibrio","fortalecimento geral","treino em casa"]', '["dor no punho","dor no ombro","dor lombar","instabilidade de ombro","lesao recente em punhos ou ombros"]', '["dor no punho","dor no ombro","dor lombar","instabilidade de ombro","lesao recente em punhos ou ombros"]', '["Apoie maos no chao abaixo dos ombros.","Estenda as pernas para tras e afaste os pes para ganhar estabilidade.","Empurre o chao, mantendo nuca longa e abdomen ativo.","Toque a mao direita no ombro esquerdo.","Volte ao apoio e toque a mao esquerda no ombro direito.","Alterne devagar sem deixar o quadril girar."]', '["Afaste mais os pes, contraia levemente gluteos e reduza a velocidade ate o tronco ficar estavel.","apoie joelhos no chao se precisar adaptar","nao deixe o quadril cair"]', '["Respire curto e continuo, expirando ao tocar o ombro."]', '["Girar quadris, afundar a lombar ou apoiar maos muito a frente dos ombros."]', '["apoie joelhos no chao se precisar adaptar","nao deixe o quadril cair","pare se punhos ou ombros doerem","mantenha respiracao fluida"]', '2026-09-30T12:15:52.234Z', '2026-09-30T12:15:52.234Z'),
('cmuo2jtf000542gzmz60m664f', 'ref_006_mov_05', 'Agachamentos', 'BODY_MOVEMENT', 'HOME_FUNCTIONAL', 'PHYSICAL', 1, 1, 'REPS_BASED', 'Movimento de descida e subida usando peso corporal, com joelhos alinhados e quadril indo para tras.', 'Pode ajudar a fortalecer pernas e gluteos.', 300, 2, '90 repeticoes', 45, 'MODERATE', 'Nenhum ou colchonete', 'ref_006_mov_05', 'ref_006_mov_05-guided-animation', '["fortalecer pernas","fortalecer gluteos","fortalecimento geral","melhorar condicionamento","sedentarismo","rotina matinal"]', '["dor no joelho","dor no quadril","dor lombar","instabilidade","lesao recente"]', '["dor no joelho","dor no quadril","dor lombar","instabilidade","lesao recente"]', '["Fique em pe com pes na largura do quadril ou um pouco mais abertos.","Mantenha peito aberto e abdomen ativo.","Leve o quadril para tras iniciando a descida.","Dobre joelhos mantendo alinhamento com os pes.","Pare em amplitude confortavel.","Suba empurrando o chao e contraindo gluteos sem travar joelhos."]', '["Reduza a profundidade, mantenha peso distribuido no pe inteiro e pense em abrir levemente os joelhos na linha dos pes.","comece com amplitude pequena","use cadeira como referencia se necessario"]', '["Inspire na descida e expire ao subir."]', '["Deixar joelhos cairem para dentro, levantar calcanhares ou desabar o tronco."]', '["comece com amplitude pequena","use cadeira como referencia se necessario","nao prenda o ar","pare se joelho ou quadril doerem"]', '2026-09-30T12:15:52.236Z', '2026-09-30T12:15:52.236Z'),
('cmuo2jtf200552gzmblgc16uk', 'ref_006_mov_06', 'Avancos / passadas', 'BODY_MOVEMENT', 'HOME_FUNCTIONAL', 'PHYSICAL', 3, 3, 'REPS_BASED', 'Passada a frente com descida controlada, alternando pernas e mantendo joelho alinhado.', 'Pode ajudar a fortalecer pernas, gluteos e estabilidade unilateral.', 300, 2, '70 repeticoes cada perna', 50, 'MODERATE', 'Nenhum ou colchonete', 'ref_006_mov_06', 'ref_006_mov_06-guided-animation', '["fortalecer pernas","fortalecer gluteos","equilibrio","fortalecimento geral","melhorar condicionamento"]', '["dor no joelho","dor no quadril","instabilidade","dor lombar","lesao recente"]', '["dor no joelho","dor no quadril","instabilidade","dor lombar","lesao recente"]', '["Fique em pe com postura alta.","De um passo a frente com distancia confortavel.","Desca dobrando os dois joelhos sem bater o joelho de tras no chao.","Mantenha o joelho da frente alinhado ao pe.","Empurre o chao para voltar.","Alterne as pernas mantendo ritmo controlado."]', '["Aumente um pouco a distancia da passada, desca verticalmente e mantenha o peso distribuido entre pe da frente e ponta do pe de tras.","use apoio lateral se necessario","comece sem profundidade"]', '["Inspire ao descer e expire ao voltar para cima."]', '["Dar passada curta demais, deixar o joelho da frente cair para dentro ou inclinar o tronco em excesso."]', '["use apoio lateral se necessario","comece sem profundidade","nao force amplitude","interrompa se houver dor no joelho"]', '2026-09-30T12:15:52.238Z', '2026-09-30T12:15:52.238Z'),
('cmuo2jtf400562gzm5g4iv6mf', 'ref_006_mov_07', 'Coice de gluteo', 'BODY_MOVEMENT', 'HOME_FUNCTIONAL', 'PHYSICAL', 1, 1, 'REPS_BASED', 'Em quatro apoios, eleva uma perna flexionada ativando gluteo sem arquear a lombar.', 'Pode ajudar a fortalecer gluteos e estabilizar quadril.', 240, 2, '45 repeticoes cada perna', 35, 'MODERATE', 'Colchonete', 'ref_006_mov_07', 'ref_006_mov_07-guided-animation', '["fortalecer gluteos","fortalecer pernas","estabilidade corporal","treino em casa","sem equipamentos","sedentarismo"]', '["dor lombar","dor no joelho","dor no quadril","lesao recente","desconforto em quatro apoios"]', '["dor lombar","dor no joelho","dor no quadril","lesao recente","desconforto em quatro apoios"]', '["Entre em quatro apoios com maos abaixo dos ombros.","Mantenha joelhos abaixo dos quadris e abdomen ativo.","Flexione o joelho de uma perna a cerca de 90 graus.","Eleve o pe em direcao ao teto sem arquear a lombar.","Pause pouco no alto sentindo gluteo.","Desca com controle e repita antes de trocar o lado."]', '["Diminua a altura da perna, mantenha a pelve apontada para o chao e imagine o abdomen sustentando a lombar.","apoie antebracos ou use colchonete se punhos incomodarem","evite arquear a lombar"]', '["Expire ao elevar a perna e inspire ao voltar."]', '["Subir a perna alem do controle e compensar com lombar ou giro do quadril."]', '["apoie antebracos ou use colchonete se punhos incomodarem","evite arquear a lombar","nao use impulso","pare se joelho ou quadril doerem"]', '2026-09-30T12:15:52.240Z', '2026-09-30T12:15:52.240Z'),
