('cmuo2jtfq005g2gzmkl799kgl', 'contagem-palavras-texto', 'Contagem de palavras em texto', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Treina atencao sustentada, precisao mental e resistencia contra distracoes usando um texto fisico.', 'Ajuda a manter foco em uma tarefa simples por mais tempo, reduzindo impulsividade e dispersao.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Livro, revista ou texto fisico', 'contagem-palavras-texto', 'contagem-palavras-texto-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Pare se houver frustracao intensa ou dor de cabeca; retome com um trecho menor."]', '["Pare se houver frustracao intensa ou dor de cabeca; retome com um trecho menor."]', '["Escolha um livro, revista ou texto fisico.","Conte mentalmente as palavras de um paragrafo.","Repita a contagem para confirmar se esta correta.","Aguarde um minuto.","Conte as palavras de dois paragrafos.","Quando ficar facil, avance para uma pagina inteira.","Faca a contagem mentalmente, sem usar os dedos para apontar."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Use textos curtos no inicio."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Pare se houver frustracao intensa ou dor de cabeca; retome com um trecho menor.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.262Z', '2026-09-30T12:15:52.262Z'),
('cmuo2jtfs005h2gzmsg8v2516', 'contagem-mental-direta-reversa', 'Contagem mental direta e reversa', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Exercicio simples para treinar concentracao, continuidade mental e controle da atencao.', 'Ajuda a mente a permanecer em uma sequencia logica sem se perder.', 120, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'contagem-mental-direta-reversa', 'contagem-mental-direta-reversa-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Evite usar como cobranca; a pratica deve ficar simples e repetivel."]', '["Evite usar como cobranca; a pratica deve ficar simples e repetivel."]', '["Conte mentalmente de 1 ate 100.","Ao terminar, conte de 100 ate 1.","Repita o exercicio pelo menos 3 vezes ao dia.","Se se perder, volte alguns numeros sem se julgar."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Pode ser feito sentado, em pe ou em uma pausa curta."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Evite usar como cobranca; a pratica deve ficar simples e repetivel.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.264Z', '2026-09-30T12:15:52.264Z'),
('cmuo2jtfu005i2gzm63iopeda', 'contagem-mental-3-em-3', 'Contagem mental de 3 em 3', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 3, 3, 'TIME_BASED', 'Exercicio de foco com raciocinio logico leve.', 'Estimula atencao, memoria operacional e controle mental.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'contagem-mental-3-em-3', 'contagem-mental-3-em-3-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Reduza a meta se a pratica aumentar irritacao."]', '["Reduza a meta se a pratica aumentar irritacao."]', '["Conte de 1 a 100 de 3 em 3: 1, 4, 7, 10.","Depois conte de 100 ate 1 da mesma forma: 100, 97, 94.","Faca lentamente e sem pressa.","Se errar, recomece de um ponto confortavel."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","O erro faz parte do treino de retomada de foco."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Reduza a meta se a pratica aumentar irritacao.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.266Z', '2026-09-30T12:15:52.266Z'),
('cmuo2jtfv005j2gzmssmt4pjh', 'repeticao-mental-frase-inspiradora', 'Repeticao mental de frase inspiradora', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Exercicio de foco verbal e estabilidade mental.', 'Ajuda a reduzir pensamentos dispersos e manter a mente em um unico conteudo.', 300, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'repeticao-mental-frase-inspiradora', 'repeticao-mental-frase-inspiradora-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Evite frases que tragam pressao, culpa ou comparacao."]', '["Evite frases que tragam pressao, culpa ou comparacao."]', '["Escolha uma palavra ou frase inspiradora.","Repita mentalmente por 5 minutos.","Quando ficar facil, aumente para 10 minutos.","Sempre que a mente divagar, volte para a frase sem se julgar."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Escolha uma frase neutra e segura para voce."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Evite frases que tragam pressao, culpa ou comparacao.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.268Z', '2026-09-30T12:15:52.268Z'),
('cmuo2jtfx005k2gzm92lijdj6', 'observacao-consciente-fruta', 'Observacao consciente de uma fruta', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Exercicio de atencao plena usando percepcao sensorial.', 'Fortalece presenca, observacao e conexao com o momento atual.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'observacao-consciente-fruta', 'observacao-consciente-fruta-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Evite se o alimento for gatilho emocional; use outro objeto."]', '["Evite se o alimento for gatilho emocional; use outro objeto."]', '["Pegue uma fruta: banana, maca, laranja, pera ou similar.","Segure-a nas maos.","Observe superficie, forma, textura, cheiro e peso.","Nao pense sobre origem, valor nutricional ou historias relacionadas.","Apenas observe a fruta como ela e."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","A pratica pode ser feita com qualquer objeto seguro se nao houver fruta."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Evite se o alimento for gatilho emocional; use outro objeto.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.269Z', '2026-09-30T12:15:52.269Z'),
('cmuo2jtfz005l2gzmejtdd5yq', 'visualizacao-mental-fruta', 'Visualizacao mental da fruta', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 3, 3, 'TIME_BASED', 'Continua o exercicio anterior com foco em memoria visual.', 'Treina concentracao, imaginacao visual e memoria sensorial.', 240, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'visualizacao-mental-fruta', 'visualizacao-mental-fruta-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Abra os olhos se surgir desconforto ou tontura."]', '["Abra os olhos se surgir desconforto ou tontura."]', '["Observe uma fruta por 2 minutos.","Feche os olhos.","Tente visualizar a fruta em sua mente.","Lembre textura, cor, deformacoes, cheiro e sensacao ao toque.","Se a imagem desaparecer, abra os olhos e observe novamente.","Repita o processo."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Visualizacao fraca tambem treina atencao; nao precisa parecer uma foto."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Abra os olhos se surgir desconforto ou tontura.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.272Z', '2026-09-30T12:15:52.272Z'),
('cmuo2jtg1005m2gzmyd9ut7cd', 'contemplacao-objeto-cotidiano', 'Contemplacao de objeto cotidiano', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Exercicio de foco visual e reducao de pensamento automatico.', 'Ajuda a contemplar um objeto sem julgamento ou associacao mental.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'contemplacao-objeto-cotidiano', 'contemplacao-objeto-cotidiano-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Escolha um objeto emocionalmente neutro."]', '["Escolha um objeto emocionalmente neutro."]', '["Escolha um objeto cotidiano: copo, colher, caderno ou caneta.","Observe o objeto em silencio.","Evite pensamentos sobre uso, nome, valor ou lembrancas.","Apenas contemple forma, cor e presenca do objeto."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Se a mente comentar, perceba e volte para a forma do objeto."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Escolha um objeto emocionalmente neutro.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.273Z', '2026-09-30T12:15:52.273Z'),
('cmuo2jtg3005n2gzmr3jn1iy3', 'observacao-triangulo-desenhado', 'Observacao de triangulo desenhado', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Exercicio de concentracao visual com estimulo geometrico simples.', 'Treina foco fixo e resistencia a distracoes.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Papel e caneta', 'observacao-triangulo-desenhado', 'observacao-triangulo-desenhado-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Interrompa se houver desconforto visual."]', '["Interrompa se houver desconforto visual."]', '["Desenhe um triangulo em uma folha.","Pinte com a cor que preferir.","Coloque a folha a sua frente.","Observe apenas o triangulo.","Evite qualquer pensamento ou distracao.","Mantenha a atencao no desenho."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Use uma cor confortavel para os olhos."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Interrompa se houver desconforto visual.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.275Z', '2026-09-30T12:15:52.275Z'),
('cmuo2jtg5005o2gzml45dsja3', 'visualizacao-triangulo-olhos-fechados', 'Visualizacao do triangulo com olhos fechados', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 3, 3, 'TIME_BASED', 'Exercicio de foco visual interno.', 'Treina memoria visual, concentracao e imaginacao controlada.', 240, NULL, NULL, NULL, 'VERY_LIGHT', 'Papel e caneta', 'visualizacao-triangulo-olhos-fechados', 'visualizacao-triangulo-olhos-fechados-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Abra os olhos se ficar desconfortavel."]', '["Abra os olhos se ficar desconfortavel."]', '["Observe o triangulo desenhado.","Quando estiver concentrado, feche os olhos.","Visualize o triangulo mentalmente.","Se a imagem sumir, abra os olhos, observe novamente e repita."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","A imagem pode oscilar; voltar faz parte do treino."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Abra os olhos se ficar desconfortavel.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.277Z', '2026-09-30T12:15:52.277Z'),
('cmuo2jtg7005p2gzmgx9qa2f2', 'visualizacao-triangulo-olhos-abertos', 'Visualizacao do triangulo com olhos abertos', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 5, 5, 'TIME_BASED', 'Exercicio avancado de visualizacao e foco mental.', 'Ajuda a manter uma imagem mental mesmo sem olhar diretamente para ela.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Papel e caneta', 'visualizacao-triangulo-olhos-abertos', 'visualizacao-triangulo-olhos-abertos-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Nao force se houver fadiga visual ou dor de cabeca."]', '["Nao force se houver fadiga visual ou dor de cabeca."]', '["Observe o triangulo.","Tire o desenho do seu campo de visao.","Com os olhos abertos, tente visualizar o triangulo mentalmente.","Mantenha a imagem pelo maior tempo possivel.","Volte ao desenho se precisar reiniciar."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Pratique depois dos exercicios anteriores."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Nao force se houver fadiga visual ou dor de cabeca.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.279Z', '2026-09-30T12:15:52.279Z'),
('cmuo2jtg8005q2gzm6cs53v6m', 'silencio-mental', 'Silencio mental', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 5, 5, 'TIME_BASED', 'Exercicio avancado para reduzir fluxo excessivo de pensamentos.', 'Ajuda a experimentar momentos de silencio mental, presenca e autorregulacao.', 300, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'silencio-mental', 'silencio-mental-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Evite transformar em luta mental. Se ficar angustiante, use respiracao simples ou procure apoio profissional."]', '["Evite transformar em luta mental. Se ficar angustiante, use respiracao simples ou procure apoio profissional."]', '["Pratique por pelo menos 5 minutos ao dia.","De preferencia ao periodo da manha.","Sente-se confortavelmente.","Tente parar ou reduzir os pensamentos.","Apenas aprecie o silencio mental.","Caso pensamentos aparecam, perceba e volte ao silencio."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Nao e necessario zerar pensamentos; notar e voltar ja e pratica."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Evite transformar em luta mental. Se ficar angustiante, use respiracao simples ou procure apoio profissional.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.281Z', '2026-09-30T12:15:52.281Z'),
('cmuo2jtga005r2gzmdirn3o4w', 'meditacao-mindfulness', 'Meditacao mindfulness', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Pratica baseada em atencao plena para reduzir agitacao mental e melhorar presenca.', 'Ensina a observar pensamentos sem se prender a eles.', 180, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'meditacao-mindfulness', 'meditacao-mindfulness-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Se observar pensamentos aumentar angustia, abra os olhos e volte para o ambiente."]', '["Se observar pensamentos aumentar angustia, abra os olhos e volte para o ambiente."]', '["Sente-se com apoio.","Foque na respiracao.","Quando pensamentos surgirem, note e volte ao ar entrando e saindo.","Se preferir, use audio guiado.","Comece com 3 a 5 minutos e progrida para 10."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","A pratica e retorno gentil, nao mente vazia perfeita."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Se observar pensamentos aumentar angustia, abra os olhos e volte para o ambiente.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.283Z', '2026-09-30T12:15:52.283Z'),
