('cmuo2jtgg005u2gzmcc5naz0n', 'visualizacao-tarefa-sucesso', 'Visualizacao de tarefa realizada com sucesso', 'FOCUS', 'FOCUS_TRAINING', 'MENTAL', 1, 1, 'TIME_BASED', 'Prepara a mente para iniciar estudo ou trabalho com menos resistencia.', 'Ajuda a organizar ambiente, imaginar execucao e reduzir travamento inicial.', 60, NULL, NULL, NULL, 'VERY_LIGHT', 'Nenhum', 'visualizacao-tarefa-sucesso', 'visualizacao-tarefa-sucesso-guided-animation', '["Quando o check-in indicar falta de foco.","Antes de estudar, trabalhar ou voltar para uma tarefa."]', '["Se a visualizacao virar preocupacao, volte para respiracao consciente."]', '["Se a visualizacao virar preocupacao, volte para respiracao consciente."]', '["Feche ou suavize os olhos.","Imagine o ambiente organizado.","Visualize voce iniciando a tarefa.","Imagine o resultado positivo e realista.","Abra os olhos e faca o primeiro passo."]', '["Use uma postura confortavel.","Reduza estimulos ao redor.","Imagine um resultado possivel, nao perfeito."]', '["Respire sem prender o ar.","Volte com calma quando a mente divagar.","Finalize percebendo seu estado atual."]', '["Fazer com pressa.","Transformar erro em julgamento.","Aumentar dificuldade antes da base ficar confortavel."]', '["Se a visualizacao virar preocupacao, volte para respiracao consciente.","Esta pratica treina atencao e nao promete resultado garantido."]', '2026-09-30T12:15:52.289Z', '2026-09-30T12:15:52.289Z'),
