('cmuo2jtgn005y2gzmo3kuddba', 'alongamento-matinal', 'Alongamento matinal', 'ENERGY', 'ENERGY_GIVE', 'MENTAL', 1, 1, 'MOBILITY', 'Espreguicar e esticar o corpo ao acordar pode ajudar a lubrificar articulacoes, despertar musculos e iniciar o dia com consciencia corporal.', 'Acordar corpo e mente sem intensidade alta.', 180, NULL, NULL, NULL, 'LIGHT', 'Nenhum', 'alongamento-matinal', 'alongamento-matinal-guided-animation', '["energia baixa","rigidez matinal","corpo parado"]', '["Nao force articulacoes ao acordar; pare se houver dor aguda ou tontura."]', '["Nao force articulacoes ao acordar; pare se houver dor aguda ou tontura."]', '["Sente-se ou fique em pe com apoio.","Eleve os bracos sem forcar.","Incline o tronco suavemente para os lados.","Movimente pescoço e ombros com amplitude pequena.","Finalize com respiracao lenta."]', '["Mantenha movimentos controlados.","Use amplitude confortavel.","Adapte intensidade ao check-in do dia."]', '["Nao prenda a respiracao.","Reduza ritmo se a respiracao sair do controle.","Finalize voltando ao ritmo natural."]', '["Buscar intensidade maior que o necessario.","Ignorar dor ou tontura.","Pular aquecimento em praticas mais ativas."]', '["Nao force articulacoes ao acordar; pare se houver dor aguda ou tontura."]', '2026-09-30T12:15:52.296Z', '2026-09-30T12:15:52.296Z'),
('cmuo2jtgp005z2gzm95xsjbjq', 'caminhada-leve-moderada', 'Caminhada leve a moderada', 'ENERGY', 'ENERGY_GIVE', 'MENTAL', 1, 1, 'WALKING', 'Caminhada de 20 a 30 minutos, preferencialmente ao ar livre, pode ajudar no estado de alerta e na circulacao.', 'Aumentar disposicao com movimento ritmado e luz natural quando possivel.', 1200, NULL, NULL, NULL, 'LIGHT', 'Nenhum', 'caminhada-leve-moderada', 'caminhada-leve-moderada-guided-animation', '["luz natural","caminhada","alerta"]', '["Evite sol forte, calor excessivo ou locais inseguros. Pare se houver falta de ar intensa."]', '["Evite sol forte, calor excessivo ou locais inseguros. Pare se houver falta de ar intensa."]', '["Escolha um trajeto seguro.","Comece em ritmo leve por 3 minutos.","Caminhe em ritmo confortavel.","Observe luz, ar e postura.","Termine reduzindo o ritmo."]', '["Mantenha movimentos controlados.","Use amplitude confortavel.","Adapte intensidade ao check-in do dia."]', '["Nao prenda a respiracao.","Reduza ritmo se a respiracao sair do controle.","Finalize voltando ao ritmo natural."]', '["Buscar intensidade maior que o necessario.","Ignorar dor ou tontura.","Pular aquecimento em praticas mais ativas."]', '["Evite sol forte, calor excessivo ou locais inseguros. Pare se houver falta de ar intensa."]', '2026-09-30T12:15:52.298Z', '2026-09-30T12:15:52.298Z'),
